<div class="result-block" v-if="allMes.fightMes"><div class="result-tips" v-if="allMes.wildMonster?.name&amp;&amp;!allMes.fightMes.result==='win'">捕捉 {{allMes.wildMonster.name}} {{allMes.fightMes.result==="catch"?"成功":"失败"}}!</div><div class="result-tips" v-if="allMes.fightMes.result==='win'"><div v-for="monster in allMes.fightMes.botMes.monsterList" :key="monster.name">你击败了 {{monster.name}}!</div></div><div class="result-tips" v-if="allMes.fightMes.result==='lose'">你被击败了!</div><div class="result-tips">获取金币：{{goldNum}}</div><div class="result-tip-for-block"><div class="result-tip-for" v-for="item in allMes.fightMes.myMes.monsterList" :key="item.name"><div class="result-tips" v-if="item.onGround">{{item.name}} 获得 {{experienceText}} 经验</div><div class="result-tips" v-show="(upgradeList.length&gt;0)&amp;&amp;(one.name===item.name)" v-for="one in upgradeList" :key="one.name"><div class="result-tips-one">{{item.name}} 从 {{one.oldLv}} 级 升级到 {{one.lv}} 级!</div><div class="result-tips-one" v-for="skill in getSkillList(one.oldLv,one.lv,one.name)">学会了技能 {{skill}}</div></div><div class="result-tips-evolution" v-if="checkCanEvolution(item.name)">{{item.name}}可以进化了！</div></div></div><div class="result-button" @click="confirm()">确认</div></div>